--------------------------------------------------
-- OIL COURSE PREVIEW
--
-- SERVER ONLY
--
-- PURPOSE:
--
-- Creates the non-gameplay LobbyCourse preview.
--
-- IMPORTANT:
--
-- This is VISUAL ONLY.
--
-- It does NOT:
--
-- - Generate oil rewards
-- - Set authoritative OilAmount
-- - Set OilType
-- - Set Positive
-- - Enable collection
-- - Participate in gameplay
--
-- The authoritative player course is generated by:
--
--     OilCourseGenerator
--
--------------------------------------------------


--------------------------------------------------
-- SERVICES
--------------------------------------------------

local ServerStorage =
	game:GetService("ServerStorage")


--------------------------------------------------
-- REFERENCES
--------------------------------------------------

local templates =
	ServerStorage:WaitForChild(
		"Templates"
	)


local oilRowTemplate =
	templates:WaitForChild(
		"OilRow"
	)



local course =
	workspace:WaitForChild(
		"Course"
	)


--------------------------------------------------
-- SETTINGS
--
-- MUST MATCH OilCourseGenerator.
--------------------------------------------------

local NUMBER_OF_ROWS =
	12


local ROW_SPACING =
	42


local PLATFORM_SEPARATION =
	5


--------------------------------------------------
-- START POSITION
--
-- MUST MATCH OilCourseGenerator.
--------------------------------------------------

local START_POSITION =
	Vector3.new(
		-64.718,
		67.994,
		-154.612
	)


--------------------------------------------------
-- PREVIEW COLOR
--------------------------------------------------

-- Preview colours (see previewColors below), for the lobby preview only. Its first row always
-- shows one green and one red platform; the real course (OilCourseGenerator) is unchanged.
local PREVIEW_GREEN = Color3.fromRGB(40, 222, 72)
local PREVIEW_RED = Color3.fromRGB(236, 42, 52)
local previewRng = Random.new()
-- Every row gets believable green / red colours (mostly one of each, now and then two of a kind);
-- the first row is always green + red. The "???" labels still hide the amounts.
local rowColors = {} -- [rowNumber] = { Left, Right }
local function previewColors(rowNumber)
	local cached = rowColors[rowNumber]
	if cached then
		return cached
	end
	local roll = previewRng:NextNumber()
	local leftGreen, rightGreen
	if rowNumber == 1 or roll >= 0.3 then
		leftGreen = previewRng:NextInteger(0, 1) == 1
		rightGreen = not leftGreen
	elseif roll < 0.15 then
		leftGreen, rightGreen = true, true
	else
		leftGreen, rightGreen = false, false
	end
	cached = {
		Left = leftGreen and PREVIEW_GREEN or PREVIEW_RED,
		Right = rightGreen and PREVIEW_GREEN or PREVIEW_RED,
	}
	rowColors[rowNumber] = cached
	return cached
end

local PREVIEW_COLOR =
	Color3.fromRGB(
		100,
		100,
		100
	)


--------------------------------------------------
-- REMOVE OLD PREVIEW
--
-- Only remove LobbyCourse.
--
-- NEVER remove PlayerCourse_* here.
--------------------------------------------------

local oldPreview =
	course:FindFirstChild(
		"LobbyCourse"
	)


if oldPreview then

	print(
		"[OilCoursePreview] Removing old LobbyCourse"
	)

	oldPreview:Destroy()

end


--------------------------------------------------
-- CREATE PREVIEW FOLDER
--------------------------------------------------

local lobbyCourse =
	Instance.new(
		"Folder"
	)


lobbyCourse.Name =
	"LobbyCourse"


--------------------------------------------------
-- PREVIEW ATTRIBUTES
--------------------------------------------------

lobbyCourse:SetAttribute(
	"Preview",
	true
)


lobbyCourse:SetAttribute(
	"RowCount",
	NUMBER_OF_ROWS
)


lobbyCourse:SetAttribute(
	"RowSpacing",
	ROW_SPACING
)


lobbyCourse:SetAttribute(
	"PlatformSeparation",
	PLATFORM_SEPARATION
)


--------------------------------------------------
-- GET PLATFORM PARTS
--------------------------------------------------

local function getPlatformParts(
	platform
)

	local parts = {}


	if not platform then

		return parts

	end


	if platform:IsA("BasePart") then

		table.insert(
			parts,
			platform
		)


	elseif platform:IsA("Model") then

		for _, object in ipairs(
			platform:GetDescendants()
		) do

			if object:IsA("BasePart") then

				table.insert(
					parts,
					object
				)

			end

		end

	end


	return parts

end


--------------------------------------------------
-- GET PLATFORM CFRAME
--
-- Matches OilCourseGenerator.
--------------------------------------------------

local function getPlatformCFrame(
	platform
)

	if not platform then

		return nil

	end


	if platform:IsA("BasePart") then

		return platform.CFrame

	end


	if platform:IsA("Model") then

		return platform:GetPivot()

	end


	return nil

end


--------------------------------------------------
-- MOVE PLATFORM HORIZONTALLY
--
-- Matches OilCourseGenerator behavior.
--------------------------------------------------

local function offsetPlatformX(
	platform,
	offsetX
)

	local currentCFrame =
		getPlatformCFrame(
			platform
		)


	if not currentCFrame then

		return false

	end


	local targetCFrame =
		currentCFrame
		+
		Vector3.new(
			offsetX,
			0,
			0
		)


	if platform:IsA("BasePart") then

		platform.CFrame =
			targetCFrame


	elseif platform:IsA("Model") then

		platform:PivotTo(
			targetCFrame
		)


	else

		return false

	end


	return true

end


--------------------------------------------------
-- SPACE PLATFORMS
--
-- MUST MATCH OilCourseGenerator.
--
-- The template's original separation is not assumed.
--------------------------------------------------

local function spacePlatforms(
	left,
	right
)

	local leftCFrame =
		getPlatformCFrame(
			left
		)


	local rightCFrame =
		getPlatformCFrame(
			right
		)


	if not leftCFrame
		or not rightCFrame then

		return false

	end


	local currentDistance =
		math.abs(
			rightCFrame.Position.X
			-
			leftCFrame.Position.X
		)


	--------------------------------------------------
	-- Already sufficiently separated.
	--------------------------------------------------

	if currentDistance >=
		PLATFORM_SEPARATION then

		return true

	end


	--------------------------------------------------
	-- Calculate midpoint.
	--------------------------------------------------

	local midpointX =
		(
			leftCFrame.Position.X
			+
			rightCFrame.Position.X
		)
		/
		2


	--------------------------------------------------
	-- Calculate target positions.
	--------------------------------------------------

	local leftTargetX =
		midpointX
		-
		(
			PLATFORM_SEPARATION
			/
			2
		)


	local rightTargetX =
		midpointX
		+
		(
			PLATFORM_SEPARATION
			/
			2
		)


	--------------------------------------------------
	-- Calculate offsets.
	--------------------------------------------------

	local leftOffset =
		leftTargetX
		-
		leftCFrame.Position.X


	local rightOffset =
		rightTargetX
		-
		rightCFrame.Position.X


	--------------------------------------------------
	-- Move left.
	--------------------------------------------------

	if not offsetPlatformX(
		left,
		leftOffset
	) then

		return false

	end


	--------------------------------------------------
	-- Move right.
	--------------------------------------------------

	if not offsetPlatformX(
		right,
		rightOffset
	) then

		return false

	end


	return true

end


--------------------------------------------------
-- REMOVE GAMEPLAY ATTRIBUTES
--
-- The preview must never contain authoritative
-- reward information.
--------------------------------------------------

local function clearGameplayAttributes(
	platform
)

	if not platform then

		return

	end


	platform:SetAttribute(
		"OilAmount",
		nil
	)


	platform:SetAttribute(
		"OilType",
		nil
	)


	platform:SetAttribute(
		"Positive",
		nil
	)


	platform:SetAttribute(
		"Collected",
		nil
	)

end


--------------------------------------------------
-- CONFIGURE PREVIEW PLATFORM
--------------------------------------------------

local function configurePreviewPlatform(
	platform,
	color
)

	if not platform then

		return false

	end


	--------------------------------------------------
	-- REMOVE GAMEPLAY DATA.
	--------------------------------------------------

	clearGameplayAttributes(
		platform
	)


	--------------------------------------------------
	-- VISUAL / PHYSICS SETTINGS.
	--------------------------------------------------

	local parts =
		getPlatformParts(
			platform
		)


	if #parts == 0 then

		warn(
			"[OilCoursePreview] Platform has no BaseParts:",
			platform:GetFullName()
		)

		return false

	end


	for _, part in ipairs(
		parts
	) do

		part.Anchored =
			true


		part.CanCollide =
			false


		part.CanTouch =
			false


		--------------------------------------------------
		-- IMPORTANT:
		--
		-- Preview must NOT participate in spatial
		-- collection queries.
		--------------------------------------------------

		part.CanQuery =
			false


		part.Color =
			color or PREVIEW_COLOR


		-- solid, not see-through: overlapping transparent green / red panels were re-sorted
		-- every frame by the renderer and blinked between colours in the lobby
		part.Transparency =
			0

	end


	return true

end


--------------------------------------------------
-- POSITION ROW
--
-- Matches OilCourseGenerator.
--------------------------------------------------

local function positionRow(
	oilRow,
	rowNumber
)

	local rowZ =
		START_POSITION.Z
		+
		(
			(rowNumber - 1)
			* ROW_SPACING
		)


	local currentPivot =
		oilRow:GetPivot()


	local rotation =
		currentPivot
		-
		currentPivot.Position


	local targetCFrame =
		CFrame.new(
			START_POSITION.X,
			START_POSITION.Y,
			rowZ
		)
		*
		rotation


	oilRow:PivotTo(
		targetCFrame
	)

end


--------------------------------------------------
-- GENERATE PREVIEW
--------------------------------------------------

for rowNumber = 1, NUMBER_OF_ROWS do

	print(
		"[OilCoursePreview] Creating row:",
		rowNumber
	)


	--------------------------------------------------
	-- CLONE
	--------------------------------------------------

	local oilRow =
		oilRowTemplate:Clone()


	oilRow.Name =
		"PreviewRow_"
		..
		tostring(
			rowNumber
		)


	--------------------------------------------------
	-- POSITION
	--------------------------------------------------

	positionRow(
		oilRow,
		rowNumber
	)


	--------------------------------------------------
	-- FIND PLATFORMS
	--------------------------------------------------

	local left =
		oilRow:FindFirstChild(
			"OilPlatformL",
			true
		)


	local right =
		oilRow:FindFirstChild(
			"OilPlatformR",
			true
		)


	--------------------------------------------------
	-- VALIDATE PLATFORMS
	--------------------------------------------------

	if not left then

		warn(
			"[OilCoursePreview] Missing OilPlatformL in row:",
			rowNumber
		)

	end


	if not right then

		warn(
			"[OilCoursePreview] Missing OilPlatformR in row:",
			rowNumber
		)

	end


	--------------------------------------------------
	-- CONFIGURE LEFT
	--------------------------------------------------

	if left then

		configurePreviewPlatform(
			left,
			previewColors(rowNumber).Left
		)

	end


	--------------------------------------------------
	-- CONFIGURE RIGHT
	--------------------------------------------------

	if right then

		configurePreviewPlatform(
			right,
			previewColors(rowNumber).Right
		)

	end

	-- The rest of the row (the black stand under the panels) is scenery too:
	-- it stayed solid and stopped real balls rolling through the preview's
	-- spot during a run (the preview is only hidden on the runner's screen).
	for _, object in ipairs(oilRow:GetDescendants()) do
		if object:IsA("BasePart") then
			object.Anchored = true
			object.CanCollide = false
			object.CanTouch = false
			object.CanQuery = false
		end
	end


	--------------------------------------------------
	-- PARENT
	--------------------------------------------------

	-- The place uses instance streaming: far rows were never sent to players, so
	-- the preview showed a bare lane until they got close. Persistent models are
	-- always streamed in.
	if oilRow:IsA("Model") then
		oilRow.ModelStreamingMode = Enum.ModelStreamingMode.Persistent
	end

	oilRow.Parent =
		lobbyCourse

end


--------------------------------------------------
-- PARENT PREVIEW
--------------------------------------------------

lobbyCourse.Parent =
	course


--------------------------------------------------
-- VERIFY
--------------------------------------------------

local rowCount =
	0


local partCount =
	0


local collidableCount =
	0


local queryableCount =
	0


local touchableCount =
	0


for _, child in ipairs(
	lobbyCourse:GetChildren()
) do

	if child.Name:match(
		"^PreviewRow_"
	) then

		rowCount +=
			1

	end

end


for _, object in ipairs(
	lobbyCourse:GetDescendants()
) do

	if object:IsA("BasePart") then

		partCount +=
			1


		if object.CanCollide then

			collidableCount +=
				1

		end


		if object.CanQuery then

			queryableCount +=
				1

		end


		if object.CanTouch then

			touchableCount +=
				1

		end

	end

end


--------------------------------------------------
-- RESULT
--------------------------------------------------

print("================================")

print(
	"[OilCoursePreview] PREVIEW READY"
)


print(
	"[OilCoursePreview] Rows:",
	rowCount,
	"/",
	NUMBER_OF_ROWS
)


print(
	"[OilCoursePreview] Parts:",
	partCount
)


print(
	"[OilCoursePreview] Collidable:",
	collidableCount
)


print(
	"[OilCoursePreview] Queryable:",
	queryableCount
)


print(
	"[OilCoursePreview] Touchable:",
	touchableCount
)


print(
	"[OilCoursePreview] Row spacing:",
	ROW_SPACING
)


print(
	"[OilCoursePreview] Platform separation:",
	PLATFORM_SEPARATION
)

print("================================")